class NumericEntityUnescaper:
    HEX_BASE = 16
    DECIMAL_BASE = 10
    AMPERSAND = '&'
    HASH = '#'
    HEX_X_LOWER = 'x'
    HEX_X_UPPER = 'X'
    SEMICOLON = ';'

    def __init__(self):
        pass

    def replace(self, string):
        out = []
        pos = 0
        length = len(string)

        while pos < length - self.TWO():
            if self.is_numeric_entity_start(string, pos):
                result = self.process_numeric_entity(string, pos)
                if result is not None:
                    out.append(result[0])
                    pos = result[1]
                    continue

            out.append(string[pos])
            pos += 1

        return ''.join(out)

    def TWO(self):
        return 2

    def is_numeric_entity_start(self, string, pos):
        return string[pos] == self.AMPERSAND and string[pos + 1] == self.HASH

    def process_numeric_entity(self, string, pos):
        start = pos + self.TWO()
        is_hex = False
        first_char = string[start]

        if first_char == self.HEX_X_LOWER or first_char == self.HEX_X_UPPER:
            start += 1
            is_hex = True

        length = len(string)

        if start == length:
            return None

        end = self.find_hex_end(string, start)

        if end < length and string[end] == self.SEMICOLON:
            entity_value = self.try_parse_entity_value(string, start, end, is_hex)
            if entity_value is not None:
                return (chr(entity_value), end + 1)

        return None

    def find_hex_end(self, string, start):
        end = start
        length = len(string)
        while end < length and self.is_hex_char(string[end]):
            end += 1
        return end

    def try_parse_entity_value(self, string, start, end, is_hex):
        try:
            base = self.HEX_BASE if is_hex else self.DECIMAL_BASE
            return int(string[start:end], base)
        except ValueError:
            return None

    @staticmethod
    def is_hex_char(char):
        return char.isdigit() or ('a' <= char.lower() <= 'f')
